const $=<T extends Element=HTMLElement>(s:string)=>document.querySelector<T>(s)!;
const esc=(s:string)=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
let settings={...DEFAULTS},seed=42, mode:'case'|'conditions'='case';
let result=simulate(settings,seed);
let continuation=freshContinuation();
let survivalGate:Gate='power';
let monthOptions={...MONTH_DEFAULTS},monthSeed=42,monthData:MonthEnsemble|null=null,monthIndex=0,monthError='',monthRequest=0,monthExplore:MonthOutcome|null=null;
let monthWorker:Worker|null=null;
type Panel='outcomes'|'node'|'advanced'|'range'|'story'|'recovery'|'collapse'|'region'|'pathways'|'rescue'|'beyond';
let panel:Panel='pathways',selected='';
let monthReturn=false;
let protectionReceipt='';
let scenarioChangeReceipt='';
let setupFrame=0;
let storyIndex=0;
let changed:string[]=[], changeColour='#86baff', feedbackTimer=0;
let viewArea='Whole world';
let regionContext:number|null=null;
let history:{settings:Settings;seed:number;continuation:Continuation;monthOptions:MonthSettings;monthSeed:number}[]=[];
let camera={x:0,y:0,w:1000,h:700};
let density:'normal'|'compact'='normal';
type Stage='world'|'chain'|'damage'|'rescue'|'beyond';
let stage:Stage='world';
const visited=new Set<Stage>(['world']);
const stageNames:Record<Stage,string>={world:'Set the world',chain:'Watch the story',damage:'Read the damage',rescue:'Protect the world',beyond:'Beyond collapse'};
const trail:{panel:Panel;selected:string;regionContext:number|null;scroll:number;storyIndex:number;camera:typeof camera;open:string[];density:'normal'|'compact'}[]=[];
function rememberPlace(){const last=trail.at(-1);if(last&&last.panel===panel&&last.selected===selected&&last.regionContext===regionContext)return;trail.push({panel,selected,regionContext,scroll:$('#readout').scrollTop,storyIndex,camera:{...camera},density,open:Array.from(document.querySelectorAll<HTMLDetailsElement>('#readout details[open]')).map(el=>el.querySelector('summary')?.textContent||'')});}
function revealPanel(){const top=$('#readout').getBoundingClientRect().top;if(top<90)window.scrollTo({top:window.scrollY+top-96,behavior:'instant'});if(!matchMedia('(prefers-reduced-motion: reduce)').matches)$('#readout').animate([{opacity:.6,transform:'translateX(9px)'},{opacity:1,transform:'translateX(0)'}],{duration:170,easing:'ease-out'});}
function back(){const old=trail.pop();if(!old){enterStage(stage);return;}panel=old.panel;selected=old.selected;regionContext=old.regionContext;storyIndex=old.storyIndex;camera=old.camera;density=old.density;render();updateCamera();document.querySelectorAll<HTMLDetailsElement>('#readout details').forEach(el=>{el.open=old.open.includes(el.querySelector('summary')?.textContent||'');});$('#readout').scrollTop=old.scroll;revealPanel();}
function enterStage(next:Stage){scenarioChangeReceipt='';stage=next;visited.add(next);trail.length=0;selected='';regionContext=null;storyIndex=0;panel=next==='world'?'pathways':next==='chain'?'story':next==='damage'?'outcomes':next==='rescue'?'rescue':'beyond';if(next==='world')focus('origins');if(next==='rescue')focus('recovery');if(next==='damage')focus('health');render();if(next==='chain')focusStory();$('#readout').scrollTop=0;guide(({world:'Watch the story, or load a new scenario. Drag a dial up or down to change the ending.',chain:'Follow one link at a time. The circuit travels with you.',damage:'Look at what people lose—and what keeps working. Select a readout to look closer.',rescue:'You have options. Protect a lifeline and watch the chain change.',beyond:'A catastrophe can leave people alive. Explore what would threaten the survivors.'})[next]);}
function initMissionTicker(){
 const display=$('#change-text');display.tabIndex=0;let previous='';let frame=0;
 const measure=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const message=display.querySelector<HTMLElement>('.mission-message');if(!message)return;const distance=Math.max(0,message.scrollWidth-display.clientWidth);display.classList.toggle('scrolling',distance>2);display.style.setProperty('--ticker-distance',`${-distance}px`);display.style.setProperty('--ticker-duration',`${Math.max(12,distance/28+6)}s`);});};
 const update=()=>{const text=display.textContent||'';if(text!==previous||!display.querySelector('.mission-message')){previous=text;display.title=text;display.setAttribute('aria-label',text);const span=document.createElement('span');span.className='mission-message';span.textContent=text;display.replaceChildren(span);}measure();};
 new MutationObserver(update).observe(display,{childList:true,subtree:true,characterData:true});new ResizeObserver(measure).observe(display);update();
}
initMissionTicker();
function guide(message:string){$('#change-text').textContent=message;const action=document.querySelector<HTMLElement>('#change-inspect');if(action)action.hidden=true;}

let worker:Worker|null=null, requestId=0;
let range:{count:number;escalation:number;nuclear:number;health:number;worldwide:number;collapse:number}|null=null;
const deckInfo:{key:NumericKey;title:string;question:string;node:string}[]=[
  {key:'capability',title:'AI ABILITIES',question:'What can it operate?',node:'ai'},
  {key:'connectedness',title:'REGIONAL CONNECTEDNESS',question:'How easily can trouble travel?',node:'spread'},
  {key:'authority',title:'PERMISSIONS',question:'Can it act without asking?',node:'access'},
  {key:'tension',title:'WORLD TENSION',question:'How close are rivals to conflict?',node:'military'},
  {key:'verification',title:'WARNING CHECKS',question:'Can we challenge a warning?',node:'checks'},
  {key:'fallback',title:'INDEPENDENT SERVICES',question:'Can we operate without it?',node:'fallback'},
  {key:'reserves',title:'HOSPITAL BACKUP',question:'How long can services hold?',node:'hospital'},
  {key:'researchSpeed',title:'AI PROJECT PACE',question:'How much new work this month?',node:'development'}
];
deckInfo.splice(1,0,deckInfo.pop()!);
function description(key:NumericKey):{value:string;unit:string;note:string} {
  switch(key){
    case 'capability':return {value:['Suggest','Configure','Coordinate'][settings.capability],unit:['proposals only','one network','connected services'][settings.capability],note:['Can suggest a change. Cannot execute it.','Can change how calls and messages are routed.','Can run phone networks and power controls.'][settings.capability]};
    case 'connectedness':return {value:`${settings.connectedness} / 100`,unit:`${result.affectedRegions} of 6 regions hit`,note:'Regions share AI and depend on each other. Stronger links spread failures more easily, but also carry relief. The same replay stays fixed as you turn this dial.'};
    case 'authority':return {value:['Advise','Ask first','Act'][settings.authority],unit:['no execution','approval required','without asking'][settings.authority],note:['It can suggest an update, but cannot install it.','A person must approve the proposed change.','It can install an update while people use the system.'][settings.authority]};
    case 'tension':return {value:settings.tension<50?'Low':settings.tension<80?'High':'Severe',unit:`${settings.tension} / 100`,note:'Rivals on edge are more likely to believe an attack warning.'};
    case 'verification':return {value:settings.verification<40?'Weak':settings.verification<75?'Stronger':'Robust',unit:`${settings.verification} / 100 · strength`,note:!result.verificationAvailable?'The checking team needs a working channel. Open the machine to give it independent verification.':`Needs ${result.verificationMinutes} min. Decisions allow ${settings.decisionTime} min.`};
    case 'fallback':return {value:`${settings.fallback}%`,unit:'works without the network',note:'Separate ways to coordinate repairs shorten the outage.'};
    case 'reserves':return {value:`${settings.reserves}h`,unit:'of essential power',note:'Generators keep essential hospital equipment running.'};
    case 'researchSpeed':return {value:`${Math.round(settings.researchSpeed*6)}/month`,unit:'updates requested',note:`${result.updates.made} produced · ${result.updates.caught} mistakes caught · ${result.updates.releases.filter(r=>r.fault).length} faulty updates escaped. Zero pace means no new updates. Arrow keys change one update; the dial gives smaller monthly totals more room.`};
    default:return {value:String(settings[key]),unit:'',note:''};
  }
}
function initDeck(){
  $('#controls').innerHTML=deckInfo.map((d,i)=>`<article class="control-bank" data-bank="${d.key}" style="--signal:${controlColours[d.key]}"><div class="bank-top"><h2 class="bank-title">${d.title}</h2><span class="bank-number">0${i+1}</span></div><button class="bank-inspect" data-inspect="${d.node}" aria-label="Explain ${d.title.toLowerCase()}" title="What does this mean?">↗</button><p class="bank-question">${d.question}</p><div class="dial-row"><div class="dial-wrap"><button class="dial" data-key="${d.key}" role="slider" aria-label="${d.title.toLowerCase()}" aria-valuemin="${controls[d.key].min}" aria-valuemax="${controls[d.key].max}" aria-valuenow="${settings[d.key]}" title="Drag up or down. Arrow keys adjust."></button></div><div class="dial-value"></div></div><p class="control-note"></p></article>`).join('');
  document.querySelectorAll<HTMLButtonElement>('.dial').forEach(dial=>{
    const key=dial.dataset.key as NumericKey,c=controls[key];
    let startY=0,startValue=0,drag=false,recorded=false,dialBefore=result;
    dial.addEventListener('pointerdown',e=>{guide(description(key).note+' Drag up or down to change it.');dialBefore=result;startY=e.clientY;startValue=settings[key];drag=true;recorded=false;dial.setPointerCapture(e.pointerId);dial.focus();e.preventDefault();});
    dial.addEventListener('pointermove',e=>{if(!drag)return;const next=Math.max(c.min,Math.min(c.max,Math.round((key==='researchSpeed'?100*Math.pow(Math.max(0,Math.min(1,Math.sqrt(startValue/100)+(startY-e.clientY)/150)),2):startValue+(startY-e.clientY)*(c.max-c.min)/150)/c.step)*c.step));if(next!==settings[key]){if(!recorded){remember();recorded=true;}change({...settings,[key]:next},false,dialBefore);}});
    dial.addEventListener('pointerup',()=>drag=false);dial.addEventListener('pointercancel',()=>drag=false);
    dial.addEventListener('keydown',e=>{if(['ArrowUp','ArrowRight','ArrowDown','ArrowLeft','Home','End'].includes(e.key))e.preventDefault();let next=settings[key];if(['ArrowUp','ArrowRight'].includes(e.key))next+=c.step;if(['ArrowDown','ArrowLeft'].includes(e.key))next-=c.step;if(e.key==='Home')next=c.min;if(e.key==='End')next=c.max;if(next!==settings[key]){e.preventDefault();change({...settings,[key]:Math.max(c.min,Math.min(c.max,next))});}});
  });
}
function dialFraction(key:NumericKey,value:number){const c=controls[key],f=(value-c.min)/(c.max-c.min);return key==='researchSpeed'?Math.sqrt(f):f;}
function updateDeck(){for(const d of deckInfo){const bank=$(`[data-bank="${d.key}"]`),desc=description(d.key),c=controls[d.key];const dial=bank.querySelector<HTMLElement>('.dial')!;bank.querySelector<HTMLElement>('.dial-wrap')!.style.setProperty('--fill',`${270*dialFraction(d.key,settings[d.key])}deg`);dial.style.setProperty('--angle',`${-135+270*dialFraction(d.key,settings[d.key])}deg`);dial.setAttribute('aria-valuemax',String(d.key==='researchSpeed'?600:c.max));dial.setAttribute('aria-valuenow',String(d.key==='researchSpeed'?Math.round(settings[d.key]*6):settings[d.key]));dial.setAttribute('aria-valuetext',`${desc.value}, ${desc.unit}`);bank.querySelector('.dial-value')!.innerHTML=`${desc.value}<small>${desc.unit}</small>`;bank.querySelector('.control-note')!.textContent=desc.note;dial.setAttribute('title',desc.note+' Drag up or down; arrow keys adjust.');}}
function remember(){history.push({settings:{...settings},seed,continuation:validateContinuation(continuation),monthOptions:{...monthOptions},monthSeed});if(history.length>80)history.shift();}
function persist(){try{localStorage.setItem('switchboard-v1',JSON.stringify(scenarioObject()));}catch{/* Browsing can continue without storage. */}}
function feedback(before:Result){
  changed=changedNodes(before,result);
  const key=(Object.keys(settings) as (keyof Settings)[]).find(k=>settings[k]!==before.settings[k]);
  if(['researchSpeed','mistakeRate','checkEffectiveness','evaluationCapacity','waitForChecks'].includes(key||''))guide(releaseExplanation(settings,result.updates));
  else if(key==='connectedness')guide(`${result.affectedRegions} of 6 regions hit in this version of events. ${before.affectedRegions===result.affectedRegions?'No extra region is reached at this setting; working relief links still change.':'Open a region below to see how the failure reached it.'}`);
  else if(before.civilisation.crossedAt!==null&&result.civilisation.crossedAt===null)guide('You broke the collapse chain. Now check which services still need help.');
  else if(before.hospitalGap>result.hospitalGap)guide(`More breathing room for hospitals: ${result.hospitalGap?`${result.hospitalGap} hours without power.`:'their essential equipment stays powered.'}`);
  else if(before.escalation&&!result.escalation)guide('The false warning no longer starts a conflict. Now protect the services on the other branch.');
  else if(key==='verification'&&!result.verified)guide(`The warning check needs ${result.verificationMinutes} minutes; leaders allow ${settings.decisionTime}. ${!result.verificationAvailable?'It also needs a working independent channel.':result.verificationMinutes>settings.decisionTime?'Make the check faster or give leaders more time.':'It arrived in time, but missed this warning. Try another version of events.'}`);
  else if(key==='tension')guide('Tension changes how likely people are to escalate. This replay keeps the same human choices. Open Read the damage → Different versions of events to explore other endings.');
  else if(key==='reserves'&&result.hospitalGap===0)guide('Hospital power now lasts through this outage. More backup will not improve this result; try protecting another lifeline.');
  else if(key==='authority'&&settings.authority===1&&!settings.humanApproval)guide('AI must ask first. This update has not been approved, so it cannot go live.');
  else guide(summariseChange(before,result));
  const direct=deckInfo.find(d=>d.key===key)?.node||Object.keys(nodeControls).find(id=>nodeControls[id]===key);if(direct&&!changed.includes(direct))changed.push(direct);
  const action=$<HTMLButtonElement>('#change-inspect');action.hidden=false;delete action.dataset.inspect;delete action.dataset.settingReveal;if(direct){action.dataset.inspect=direct;action.textContent=`See ${nodeById[direct].title} →`;}else if(key){action.dataset.settingReveal=key;action.textContent='See the changed setting →';}else{action.hidden=true;}
  clearTimeout(feedbackTimer);
}
function clearFeedback(){changed=[];clearTimeout(feedbackTimer);}
function change(next:Settings,record=true,origin?:Result){scenarioChangeReceipt='';protectionReceipt='';cancelAnimationFrame(setupFrame);if(record)remember();const before=origin||result;settings=validateSettings(next);result=simulate(settings,seed);range=null;requestId++;feedback(before);persist();render();}


function displayNode(id:string):{status:Status;label:string}{
  const n=result.nodes[id];if(id==='collapse')return {...n,label:result.nuclear?'Aftermath unknown':result.civilisation.endStatus==='collapse'?'The world is coming apart':result.civilisation.recoveredAt!==null?'Back from the brink':result.civilisation.endStatus==='disrupted'?'Still fighting to recover':'The world holds together'};if(mode==='case'||n.status==='unknown')return n;
  const possible=result.incident;
  switch(id){
    case 'comms':return {status:possible?'exposed':'safe',label:possible?'Faulty change can execute':'Execution route blocked'};
    case 'checks':if(!result.verificationAvailable)return {status:'exposed',label:'No working check channel'};return {status:result.verificationMinutes<=settings.decisionTime?'safe':'exposed',label:result.verificationMinutes<=settings.decisionTime?'A timely check is possible':'Check misses the deadline'};
    case 'warning':return {status:possible&&settings.aiAdvice?'exposed':'quiet',label:possible&&settings.aiAdvice?'Misleading advice can enter':'This advice route is absent'};
    case 'military':return {status:result.warning&&settings.tension>=50?'exposed':'safe',label:result.warning&&settings.tension>=50?'Escalation route enabled':'This route is constrained'};
    case 'power':return {status:result.powerOutage?'exposed':'safe',label:result.powerOutage?'Shared failure can reach power':'Power is independent here'};
    case 'hospital':return {status:result.recoveryModel.healthcareGap?'exposed':'safe',label:result.recoveryModel.healthcareGap?'Care can fall below demand':'Care covers this incident'};
    case 'food':return {status:result.foodGap?'exposed':'safe',label:result.foodGap?'Fridges may lose power':'Food backup lasts'};
    case 'emergency':return {status:result.emergencyGap?'exposed':'safe',label:result.emergencyGap?'Help may be delayed':'Help can get through'};
    case 'spread':return {status:result.incident?'exposed':'safe',label:`${result.affectedRegions} regions in reach`};
    case 'repair':return {status:result.recoveryModel.status==='stalled'?'exposed':'safe',label:result.recoveryModel.status==='stalled'?'Repair support runs out':'Repair work can progress'};
    case 'recovery':return {status:'unknown',label:'Outcome depends on events'};
    default:return n;
  }
}
function wrap(text:string,max=27){const words=text.split(' '),lines:string[]=[];let line='';for(const w of words){if((line+' '+w).trim().length>max&&line){lines.push(line);line=w;}else line+=(line?' ':'')+w;}if(line)lines.push(line);return lines.slice(0,2);}
function ancestors(id:string,set=new Set<string>()):Set<string>{if(set.has(id))return set;set.add(id);for(const p of result.nodes[id]?.parents||[])ancestors(p,set);return set;}
function renderMap(){
  $('#system-state').textContent=result.nuclear?'CRITICAL ALERT':result.civilisation.endStatus==='collapse'?'WORLD IN CRISIS':result.incident||result.pathways.healthIntroduced?'WORLD UNDER PRESSURE':'WORLD HOLDING';
  $('#main').dataset.alert=result.nuclear||result.civilisation.endStatus==='collapse'?'critical':result.incident?'warning':'safe';
  $('#world-svg').classList.toggle('world-emergency',panel==='beyond'?evaluateContinuation(result,continuation).state==='assumed':result.affectedRegions===6||result.nuclear||result.civilisation.endStatus==='collapse');
  $('#main').classList.toggle('survival-view',panel==='beyond');
  if(panel==='beyond'){$('#viewport').setAttribute('aria-label','Survival story. Select one of four defences to explore.');$('#world-svg').setAttribute('aria-label','Four defences and the surviving community');$('#world-svg').innerHTML=svgDefs+survivalCanvas(result,continuation,survivalGate);$('#world-svg').setAttribute('viewBox','0 0 1080 800');$('#map-title').textContent='THE LAST REFUGES · YOUR WHAT-IF STORY';return;}
  $('#viewport').setAttribute('aria-label','Living circuit. Drag or scroll to explore. Control plus scroll zooms.');$('#world-svg').setAttribute('aria-label','Connected causes, services and recovery');$('#map-title').textContent='ONE MONTH · FOLLOW ITS CONNECTIONS';$('#world-svg').setAttribute('viewBox',`${camera.x} ${camera.y} ${camera.w} ${camera.h}`);
  $('#world-svg').classList.toggle('compact-circuit',density==='compact');
  $('#world-svg').classList.toggle('world-emergency',result.affectedRegions===6||result.nuclear||result.civilisation.endStatus==='collapse');
  const step=panel==='story'?storySteps()[storyIndex]:null;
  const linked=step?new Set(step.nodes):selected&&selected!=='nuclear'?new Set([selected,...(result.nodes[selected]?.parents||[]),...Object.keys(result.nodes).filter(id=>result.nodes[id].parents.includes(selected))]):null;
  const edges=new Map(primaryEdges.map(([a,b])=>[a+'-'+b,[a,b]]));
  for(const [id,node] of Object.entries(result.nodes))for(const parent of node.parents)if(nodeById[parent]&&nodeById[id])edges.set(parent+'-'+id,[parent,id]);
  const paths=[...edges.values()].map(([from,to])=>{const active=result.nodes[from]?.status,related=!linked||linked.has(from)&&linked.has(to),secondary=!primaryEdges.some(([a,b])=>a===from&&b===to);return `<path class="circuit-track ${secondary?'secondary':''}" d="${connection(from,to)}"/><path data-from="${from}" data-to="${to}" class="circuit-wire ${active} ${related?'':'distant'} ${linked&&related?'focused-link':''} ${secondary&&!(linked&&related)?'secondary':''}" d="${connection(from,to)}"/>`;}).join('');
  const cards=layout.map(n=>{const state=displayNode(n.id),colour=controlColours[nodeControls[n.id]]||'#d7e6f4';return `<g class="machine-node ${state.status} ${selected===n.id||step?.nodes.includes(n.id)?'selected':''} ${linked&&!linked.has(n.id)?'distant':''} ${changed.includes(n.id)?'changed':''}" data-node="${n.id}" transform="translate(${n.x} ${n.y})" tabindex="0" role="button" aria-label="${n.title}: ${esc(state.label)}. Select to explore."><title>${n.title}. ${state.label}. Select to illuminate its incoming and outgoing connections. Title colour identifies its control; the lamp shows its state.</title><rect class="socket" width="210" height="112" rx="13"/><rect class="glass" x="5" y="5" width="200" height="102" rx="10"/><rect class="selection-ring" x="8" y="8" width="194" height="96" rx="7"/><path class="glass-edge" d="M18 6 H192"/><circle class="port" cx="0" cy="56" r="3"/><circle class="port" cx="210" cy="56" r="3"/><g class="module-icon" transform="translate(16 14) scale(.72)">${icon(n.icon)}</g><circle class="lamp-bezel" cx="187" cy="23" r="9"/><circle class="module-led" cx="187" cy="23" r="5.5"/><text class="module-title" fill="${colour}" x="16" y="58">${n.title}</text>${wrap(state.label,28).map((line,i)=>`<text class="module-sub" x="16" y="${80+i*16}">${esc(line)}</text>`).join('')}</g>`;}).join('');
  $('#world-svg').innerHTML=svgDefs+livingAtlas()+`<g class="district-engraving">${districts.map((d,i)=>`<text x="${d.x}" y="40">0${i+1} / ${d.name}</text><text class="district-sub" x="${d.x}" y="64">${d.sub}</text>`).join('')}</g>`+paths+cards;

}
function outcomeCard(title:string,text:string,status:Status,id?:string){return `<button class="instrument-readout ${status}" data-inspect="${id||'collapse'}"><span class="outcome-symbol"><svg viewBox="0 0 24 24">${outcomeIcon(id||'collapse')}</svg></span><span><strong>${title}</strong><small>${text}</small></span><i class="signal-led ${status}"></i></button>`;}
function placeName(p:Panel,id:string,region:number|null){return p==='node'?(nodeById[id]?.title||'Nuclear weapons'):p==='region'?`Region ${(region??0)+1}`:({pathways:'Causes',advanced:'All controls',story:'Events',outcomes:'World status',rescue:'Safeguards',beyond:'Survival',range:'Possible events',recovery:'Repairs',collapse:'Civilisation'} as Record<string,string>)[p];}
function panelHeader(name:string){return `<div class="readout-head"><nav class="breadcrumbs" aria-label="Your location"><button data-stage="${stage}">${stageNames[stage]}</button><span> / ${placeName(panel,selected,regionContext)||name}</span></nav>${trail.length?'<button class="back-control" id="panel-back">← Back to previous view</button>':''}${selected?'<button class="small-button" id="clear-selection">Show surrounding world ↗</button>':''}</div>`;}
function evidenceNote(id:string){const e=evidenceFor(id);return e?`<p class="rule-label">WHY THIS LINK MAKES SENSE</p><p class="rule-copy">${esc(e.mechanism)}</p><p class="rule-label">WHAT WE ASSUME</p><p class="rule-copy">${esc(e.assumption)}</p>${sourceLink(e.source)}`:'';}
function sourceLink(which:keyof typeof sources){const s=sources[which];return `<a class="source-link" href="${s.url}" target="_blank" rel="noreferrer">${s.name} ↗</a>`;}
function renderPanel(){
  const el=$('#readout');
  if(panel==='outcomes'){
    const c=result.civilisation;
    el.innerHTML=panelHeader('World status')+`<div class="readout-name"><span class="etched-label">DAMAGE DURING THIS MONTH</span><h2>What happened to this world?</h2></div>`+
      outcomeCard('Military crisis',result.escalation?'A false warning pushes rivals into conflict.':'The warning does not start a conflict.',result.escalation?'harm':'safe','military')+
      outcomeCard('Region 1 · hospital',result.recoveryModel.healthcareGap?`${result.recoveryModel.healthcareGap} hours when care cannot keep up.`:'Essential care holds. People can get help.',result.nodes.hospital.status,'hospital')+
      outcomeCard('Nuclear weapons',result.nuclear?'Leaders choose to use nuclear weapons.':'No nuclear use in this replay.',result.nuclear?'harm':'quiet','nuclear')+
      outcomeCard('Civilisation',result.nuclear?'A nuclear catastrophe. What follows is unknown.':c.endStatus==='collapse'?'The lifelines fail. Recovery is still out of reach.':c.recoveredAt!==null?'Brought back from the brink. Services recover.':c.endStatus==='disrupted'?'Still standing. Still fighting to recover.':'The world holds together.',result.nodes.collapse.status,'collapse')+
      `<button class="primary-action" data-stage="rescue">Protect the world <span>→</span></button><button class="small-button" data-inspect="collapse">Could this bring civilisation down? ↗</button><button class="small-button" id="open-month">Explore other possible months ↗</button><button class="small-button" data-panel="range">Different versions of events ↗</button>`;
  } else if(panel==='collapse'){
    el.innerHTML=collapsePanel();
  } else if(panel==='beyond'){
    el.innerHTML=continuationPanel(result,continuation,survivalGate);
  } else if(panel==='region'){
    el.innerHTML=regionPanel(regionContext??0);
  } else if(panel==='recovery'){
    el.innerHTML=recoveryPanel();
  } else if(panel==='story'){
    const steps=storySteps(); storyIndex=Math.min(storyIndex,steps.length-1); const step=steps[storyIndex];
    el.innerHTML=panelHeader('SHOW WHAT HAPPENED')+`<div class="story-number">${String(storyIndex+1).padStart(2,'0')}<small> / ${steps.length}</small></div><p class="story-time">${step.time}</p><h2 class="inspector-title">${step.title}</h2><p class="story-copy" aria-live="polite">${step.copy}</p><div class="story-nav"><button id="story-prev" ${storyIndex===0?'disabled':''}>← Previous event</button><button id="story-next" ${storyIndex===steps.length-1?'disabled':''}>Next →</button></div>${storyIndex===steps.length-1?'<div class="story-finish"><p>The region lights record damage during the whole month, including services that later recovered.</p><button class="primary-action" data-stage="rescue">Protect the world →</button><button class="small-button" data-inspect="collapse">Could this bring civilisation down? ↗</button></div>':''}<div class="story-dots">${steps.map((_,i)=>`<button data-step="${i}" aria-label="Step ${i+1}" aria-current="${i===storyIndex?'step':'false'}"></button>`).join('')}</div>`;
  } else if(panel==='node'){
    const n=nodeById[selected]||{title:'Nuclear weapons',kicker:'A HUMAN DECISION'};const state=selected==='nuclear'?{...result.nodes.military,status:result.nuclear?'harm' as Status:'quiet' as Status,label:result.nuclear?'Nuclear weapons are used':'Nuclear use is avoided',reason:result.nuclear?'The false warning escalates into conflict. Leaders make a further decision to use nuclear weapons. It is a catastrophe beyond the original network failure.':'The escalation does not reach nuclear weapons in this run. Keeping checks independent and giving leaders time to verify a warning can break the route.',rule:'This requires escalation, high tension and a separate seeded human strategic-use decision. Nuclear damage is not calculated.'}:result.nodes[selected],display=regionContext!==null&&!result.civilisation.regions[regionContext].exposed?{status:'safe' as Status,label:'Available in this region'}:selected==='nuclear'?state:displayNode(selected);
    el.innerHTML=panelHeader('FOLLOW THE CONNECTION')+`<span class="etched-label">${n.kicker}</span><h2 class="inspector-title">${n.title}</h2><div class="inspector-status"><i class="status-lamp ${display.status}"></i>${esc(display.label)}</div><p class="inspector-copy">${regionContext!==null?`<strong>Region ${regionContext+1}</strong><br>${!result.civilisation.regions[regionContext].exposed?'This region uses a separate network, or the update was stopped. Its services keep working.':esc(state.reason)}`:esc(mode==='conditions'&&state.status!=='unknown'?'The highlighted route shows how this component is connected. Choose “What happens in this case” in Explore to inspect which events occurred.':state.reason)}</p><details class="model-details"><summary>How this works & sources</summary><p class="rule-label">${state.status==='unknown'?'MODEL COVERAGE':'THE RULE IN THIS MODEL'}</p><p class="rule-copy">${esc(state.rule)}</p>${evidenceNote(selected)}</details>${selected==='spread'?spreadPanel():''}${pathwayInterventions(selected)}${selected==='development'?updateDetails():''}<button class="small-button" data-panel="advanced">World settings <span>↗</span></button><button class="small-button" id="trace-selected">Watch the story <span>↗</span></button>`;
  } else if(panel==='pathways'){
    el.innerHTML=panelHeader('EXPLORE THE CAUSES')+pathwaysPanel(result);
  } else if(panel==='advanced'){
    el.innerHTML=panelHeader('World settings')+`<details class="model-details"><summary>Main dials</summary>${deckInfo.map(d=>rangeField(d.key,d.title,description(d.key).note,d.key==='reserves'?'hours':'')).join('')}</details>`+(monthReturn?'<button class="primary-action" id="open-month">← Return to the month scenario</button>':'')+`<button class="small-button" data-panel="pathways">Choose a scenario ↗</button>`+pathwayControls(rangeField,toggleField,releaseExplanation(settings,result.updates))+`<details class="model-details"><summary>Regions, reserves & repairs</summary>`+
      rangeField('connectedness','Regional connectedness','Shared AI and services let trouble travel. Working links also help neighbours send relief.','/ 100')+
      `<h3 class="recovery-controls-title">Regions & help</h3>`+
      rangeField('regionDifference','Different reserves','0 makes every region identical. Higher settings share the same total stores less evenly.','%')+
      rangeField('aidStrength','Help from working regions','Spare relief packages sent per hour, as a share of one package.','%')+
      rangeField('aidBudget','Relief stock per region','Separate surplus for helping others; domestic essentials stay protected.','packages')+
      rangeField('aidDelay','Travel time for help','A donor first stabilises for 24 hours, then help travels.','hours')+
      rangeField('responseBackup','Emergency coordination backup','How long local teams can coordinate using backup plans.','hours')+
      rangeField('foodBackup','Food backup','How long can warehouse fridges run without mains power?','hours')+
      `<h3 class="recovery-controls-title">What repairs need</h3>`+
      rangeField('repair','Repair workload','Work hours needed with a full crew and everything available.','work h')+
      rangeField('crews','Repair crews','How much of the normal repair team is available at the start?','%')+
      rangeField('repairBackup','Power for repair tools','Generator hours at repair sites. Separate from hospital backup.','hours')+
      rangeField('repairSupplies','Repair stockpile','Starting stock and storage limit. One unit supplies one full-speed hour of repair work; deliveries refill used space.','units')+
      rangeField('supplyDelivery','Independent deliveries','Supplies that can arrive without the main network or electricity.','%')+
      rangeField('foodStores','Stored food','Food available while deliveries fall short. Separate from fridge backup.','hours')+
      `<details class="model-details"><summary>Definition used for collapse</summary><p class="rule-copy">Power, healthcare, food and coordination all below half capacity, continuously:</p>`+
      rangeField('collapseRegions','Regions required','Six equal-weight regions; this is not a world population estimate.','of 6')+
      rangeField('collapseDays','Days required','A scenario definition, not a settled scientific cutoff.','days')+`</details>`+
      `</details><details class="model-details"><summary>Attack warnings & permission</summary>`+rangeField('decisionTime','Time to check','Time available before the military decision.','min')+
      toggleField('independent','Independent verification','People can check the warning using another network.')+
      toggleField('sharedProvider','Shared power control','Power controls use the same network as calls and messages.')+
      toggleField('aiAdvice','AI military advice','AI can warn leaders of an attack. People still control the weapons.')+

      toggleField('humanApproval','Allow updates to go live','Only matters when permission is “Ask first”.')+
      `</details>`;
  } else {
    el.innerHTML=panelHeader('Possible events')+`<p class="scenario-tag">SAME SETTINGS · DIFFERENT EVENTS</p><h2 class="inspector-title">Same world.<br>Different endings.</h2><p class="inspector-copy">Keep your controls fixed. Explore 256 versions of events: which updates go wrong, which mistakes escape checks, where failures spread, and how people respond.</p>`+(range?[
      ['All six regions hit',range.worldwide],['Civilisation in crisis',range.collapse],['Conflict escalates',range.escalation],['Nuclear weapons used',range.nuclear],['Hospital power fails',range.health]
    ].map(([label,count])=>`<div class="hist-row"><div><span>${label}</span><span>${count} of ${range!.count}</span></div><div class="hist-track"><i style="width:${Number(count)/range!.count*100}%"></i></div></div>`).join(''):'<p class="inspector-copy">Exploring possible events…</p>')+`<p class="rule-copy">Regional links and human decisions vary. Your controls and backup stores stay fixed.</p><button class="primary-action" id="new-case">Try another version of events ↻</button><details class="model-details"><summary>How the replay works</summary><p>The same settings and replay number reproduce the same regional links and decisions. Current replay: ${seed}. The 256 outcomes are generated by this model, not measured real-world odds.</p></details>`;
    if(!range)requestEnsemble();
  }
  if(scenarioChangeReceipt&&panel!=='advanced'&&panel!=='beyond')el.insertAdjacentHTML('afterbegin',scenarioChangeReceipt);
}

function updateDetails(){const u=result.updates;return `<div class="update-ledger"><p class="release-policy-status">${releaseExplanation(settings,u)}</p><p>${u.waiting} awaiting tests · ${u.ready} awaiting permission${result.nuclear?' · history ends at nuclear use':''}</p><button class="small-button" data-setting-reveal="mistakeRate">Mistake rate: ${settings.mistakeRate}% ↗</button><button class="small-button" data-setting-reveal="checkEffectiveness">Testing effectiveness: ${settings.checkEffectiveness}% ↗</button><details open><summary>Faulty updates that reached the world (${u.releases.filter(e=>e.fault).length})</summary>${u.releases.filter(e=>e.fault).map(e=>`<button class="release-event" data-release="${e.id}"><b>Day ${Math.floor(e.hour/24)+1} · Update ${e.id}</b><span>${e.checked?'Tests missed the mistake':'Released without testing'} → ${result.affectedRegions} regions hit</span></button>`).join('')||'<p>No faulty updates escaped. Try increasing pace or reducing the checks.</p>'}</details><button class="primary-action" id="open-month">Explore other possible months →</button></div>`;}
function rangeField(key:NumericKey,label:string,copy:string,unit:string){const c=controls[key];return `<div class="advanced-field"><label for="adv-${key}">${label}<output>${key==='researchSpeed'?`${Math.round(settings[key]*6)} updates/month`:key==='evaluationCapacity'?`${20*settings[key]/100} tests/day`:`${settings[key]} ${unit}`}</output></label><input id="adv-${key}" type="range" min="${c.min}" max="${key==='researchSpeed'?600:c.max}" step="${key==='researchSpeed'?1:c.step}" value="${key==='researchSpeed'?Math.round(settings[key]*6):settings[key]}" data-setting="${key}" data-unit="${unit}"><p>${copy}</p></div>`;}
function toggleField(key:keyof Settings,label:string,copy:string){return `<div class="advanced-field"><label for="adv-${key}">${label}<input id="adv-${key}" type="checkbox" data-setting="${key}" ${settings[key]?'checked':''}></label><p>${copy}</p></div>`;}
function render(skipPanel=false){$('#threat-readouts').innerHTML=threatReadouts(result,continuation);$('#update-flow').title=`${result.updates.mistakes-result.updates.caught-result.updates.releases.filter(e=>e.fault).length} faulty updates are still held by testing or permission. Select to see the full account.`;$('#update-flow').innerHTML=`<span>THIS MONTH</span> <b>${result.updates.made}</b> updates <i>→</i> <b>${result.updates.mistakes}</b> mistakes <i>→</i> <b class="caught">${result.updates.caught}</b> caught <i>→</i> <b class="${result.updates.releases.some(e=>e.fault)?'escaped':''}">${result.updates.releases.filter(e=>e.fault).length}</b> escaped${result.updates.waiting+result.updates.ready?` · <b class="waiting">${result.updates.waiting+result.updates.ready}</b> waiting`:""} ↗`;$('.scenario-line strong').textContent=currentScenario(settings).name+(currentScenario(settings).modified?' · adjusted':'');if(panel==='story')storyIndex=Math.min(storyIndex,storySteps().length-1);updateDeck();renderMap();renderImpact();if(!skipPanel)renderPanel();$('#undo-button').toggleAttribute('disabled',!history.length);document.querySelectorAll<HTMLElement>('[data-stage]').forEach(el=>{el.classList.toggle('active',el.dataset.stage===stage);el.classList.toggle('visited',visited.has(el.dataset.stage as Stage));if(el.dataset.stage===stage)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});}
function requestEnsemble(){const id=++requestId;try{if(!worker){worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});worker.onmessage=e=>{if(e.data.id!==requestId)return;range=e.data;if(panel==='range')renderPanel();};worker.onerror=()=>{if(panel==='range'){$('#readout').innerHTML=panelHeader('Possible events')+'<p class="inspector-copy">The replay could not start. Your current world and its controls still work.</p>';}};}worker.postMessage({settings,seed,id});}catch{$('#readout').innerHTML=panelHeader('Possible events')+'<p class="inspector-copy">This browser cannot run the replay. Your current world still works.</p>';}}

function clearSelection(){const previous=trail.pop();if(previous)camera={...previous.camera};selected='';regionContext=null;panel='outcomes';render();updateCamera();guide('Back to the surrounding world. Dim connections are still part of the model; select a component to follow them.');}
function inspect(id:string){if(id==='extinction'){showExtinction();return;}if(selected===id){clearSelection();return;}rememberPlace();regionContext=null;selected=id;panel=id==='collapse'?'collapse':id==='repair'||id==='recovery'?'recovery':'node';renderMap();renderPanel();$('#readout').scrollTop=0;focusNode(id);revealPanel();}
function setPanel(next:Panel){if(next===panel)return;rememberPlace();regionContext=null;panel=next;if(next!=='node')selected='';renderMap();renderPanel();$('#readout').scrollTop=0;revealPanel();}
function toast(text:string){$('#toast').textContent=text;$('#toast').classList.add('visible');window.setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function openDialog(title:string,eyebrow:string,html:string){$('#dialog').classList.remove('continuation-dialog','month-dialog');$('#dialog-title').textContent=title;$('#dialog-eyebrow').textContent=eyebrow;$('#dialog-body').innerHTML=html;$<HTMLDialogElement>('#dialog').showModal();}
function showAbout(){openDialog('Your world. One month.','ABOUT THE SWITCHBOARD',`<p>Follow how an AI mistake, misuse or loss of control could interrupt essential services. Then try to break the chain.</p><h3>Inputs create events</h3><p>Project pace selects 0–600 updates per month, spread through 30 days, limited by computers and experiments. Each update may contain a mistake according to your mistake rate. Testing can check up to twenty updates a day; testing effectiveness determines how many mistakes it catches. Caught mistakes are held back. Permission and “Hold updates until tested” decide which other updates go live. Zero pace produces no updates. No hidden bad update starts the month.</p><p>The board follows all escaped faults through repairs and six fictional regions over the same 30 days. Each fault adds repair work; backups and supplies are not reset. Red lights record damage during the month, even if a service later recovers. Hospital totals describe Region 1.</p><h3>Regional connectedness</h3><p>The dial sets how easily failures travel through shared AI and services. Each replay samples shared rollouts and links between regions. Regions can receive the same faulty update or depend on services that fail elsewhere. Stronger links also carry more relief from healthy neighbours. The score is not a percentage chance of disaster. Regional links stay fixed while you adjust controls, and for every release within a month. The model applies the resulting footprint at the start of each fault; it does not time the spread between regions. Selected health and information stresses use the same regional footprint, not a separate epidemic or message-spread model.</p><h3>Different versions of events</h3><p>Replay 256 possible combinations of regional links and human responses. Your settings stay fixed; the extent of disruption and its consequences can change.</p><h3>A month of new updates</h3><p>Produce, test and release AI updates for 30 days. Faults can add up faster than crews can repair them. Explore 128 possible months using the same settings, then follow an individual month. The board and month explorer use exactly the same calculation; the first replay matches the board. Selected agent, health and information challenges remain active.</p><h3>Could anyone survive?</h3><p>Collapse does not mean extinction. Explore the further conditions that could threaten every surviving community. Your answers here are assumptions, separate from the calculated service failures.</p><h3>What the model does—and does not—measure</h3><p>It calculates permission and checking gates, repair work, backup depletion, finite help between regions and an adjustable definition of service collapse. It does not calculate deaths, nuclear devastation, detailed epidemics, financial-market contagion, recursive intelligence growth or extinction. The regions are equal-weight teaching areas, not population estimates.</p><p>Numbers and probabilities are illustrative assumptions, not measured forecasts. Sources support the mechanisms, not these numerical values. Every component offers its rule and evidence on demand.</p>${sourceLink('ai')}${sourceLink('military')}${sourceLink('resilience')}<p>Model ${MODEL_VERSION}. Runs on your device without an AI service. Worlds are saved in this browser. New-world buttons replace starting settings; Undo restores the previous world. Motion is on by default; use Motion off on the map to pause it.</p>`);}

function renderMonth(){
 if(!$('#dialog').classList.contains('month-dialog'))return;
 const open=Array.from(document.querySelectorAll<HTMLDetailsElement>('#dialog-body details[open]')).map(d=>d.querySelector('summary')?.textContent);
 const top=$('#dialog').scrollTop,active=document.activeElement as HTMLElement,key=active?.dataset.month,setting=active?.dataset.monthSetting,activeId=active?.id,activeOutcome=active?.dataset.monthOutcome,activeChallenge=active?.dataset.monthChallenge;
 $('#dialog-body').innerHTML=monthPanel(settings,monthOptions,monthData,monthIndex,monthError,monthExplore);
 document.querySelectorAll<HTMLDetailsElement>('#dialog-body details').forEach(d=>{d.open=open.includes(d.querySelector('summary')?.textContent);});
 $('#month-undo').toggleAttribute('disabled',!history.length);$('#dialog').scrollTop=top;
 if(activeId)document.getElementById(activeId)?.focus({preventScroll:true});
 if(activeOutcome)document.querySelector<HTMLElement>(`[data-month-outcome="${activeOutcome}"]`)?.focus({preventScroll:true});
 if(activeChallenge)document.querySelector<HTMLElement>(`[data-month-challenge="${activeChallenge}"]`)?.focus({preventScroll:true});
 if(key)document.querySelector<HTMLElement>(`[data-month="${key}"]`)?.focus({preventScroll:true});
 if(setting)document.querySelector<HTMLElement>(`[data-month-setting="${setting}"]`)?.focus({preventScroll:true});
}
function requestMonth(){
 const id=++monthRequest;monthData=null;monthIndex=0;monthError='';monthExplore=null;renderMonth();
 try{if(!monthWorker){monthWorker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});monthWorker.onmessage=e=>{if(e.data.id!==monthRequest)return;if(e.data.error)monthError=e.data.error;else monthData=e.data;renderMonth();};monthWorker.onerror=()=>{monthError='The month could not run. Try again.';monthWorker?.terminate();monthWorker=null;renderMonth();};}monthWorker.postMessage({kind:'month',id,settings,seed:monthSeed,options:monthOptions});}catch{monthError='This browser could not start the month scenario.';renderMonth();}
}
function showMonth(){monthSeed=seed;monthReturn=false;openDialog('Can the world keep up?','A MONTH OF NEW UPDATES','');$('#dialog').classList.add('month-dialog');requestMonth();}
$('#dialog-body').addEventListener('change',e=>{
 const input=e.target as HTMLInputElement;
 if(input.dataset.month){remember();const key=input.dataset.month as keyof MonthSettings;monthOptions={...monthOptions,[key]:Number(input.value)};if(monthOptions.checkedFault>monthOptions.uncheckedFault){if(key==='checkedFault')monthOptions.uncheckedFault=monthOptions.checkedFault;else monthOptions.checkedFault=monthOptions.uncheckedFault;}persist();requestMonth();}
 if(input.dataset.monthSetting){const key=input.dataset.monthSetting as keyof Settings;change({...settings,[key]:input.type==='checkbox'?input.checked:key==='researchSpeed'?Number(input.value)/6:Number(input.value)});requestMonth();}
});
$('#dialog-body').addEventListener('click',e=>{
 const target=e.target as Element,challenge=target.closest<HTMLElement>('[data-month-challenge]'),outcome=target.closest<HTMLElement>('[data-month-outcome]');
 if(challenge){const c=monthChallenges[challenge.dataset.monthChallenge!];remember();monthOptions={...c.options};change({...DEFAULTS,...c.settings},false);requestMonth();return;}
 if(outcome&&monthData){const category=outcome.dataset.monthOutcome as MonthOutcome;const index=monthData.runs.findIndex(r=>r.outcome===category);if(index<0){monthExplore=category;}else{monthIndex=index;monthExplore=null;}renderMonth();document.querySelector('#month-explore')?.scrollIntoView({block:'nearest'});return;}
 const id=target.closest<HTMLElement>('[id]')?.id;
 if(id==='month-prev'||id==='month-next'){monthIndex=Math.max(0,Math.min((monthData?.count||1)-1,monthIndex+(id==='month-next'?1:-1)));renderMonth();}
 if(id==='month-more'){remember();monthSeed=(monthSeed+128)>>>0;persist();requestMonth();}
 if(id==='month-use'&&monthData){remember();seed=monthData.runs[monthIndex].seed;result=simulate(settings,seed);range=null;requestId++;persist();$<HTMLDialogElement>('#dialog').close();enterStage('chain');guide('This replay is now on the board. Watch the story or change a dial to explore a different ending.');return;}
 if(id==='month-retry')requestMonth();
 if(id==='month-undo'){$('#undo-button').click();requestMonth();}
 if(id==='month-world'){monthReturn=true;$<HTMLDialogElement>('#dialog').close();setPanel('advanced');}
});

function showExtinction(){enterStage('beyond');}
function refreshContinuation(){render();$('#readout').scrollTop=0;const heading=document.querySelector<HTMLElement>('#readout h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}
function scenarioObject(){return {version:MODEL_VERSION,settings,seed,continuation,monthOptions,monthSeed};}
function loadScenario(raw:unknown){scenarioChangeReceipt='';protectionReceipt='';clearFeedback();const obj=raw as {version?:unknown;settings?:unknown;seed?:unknown;continuation?:unknown;monthOptions?:unknown;monthSeed?:unknown};if(!obj||!['0.1.0','0.2.0','0.2.1','0.3.0','0.4.0','0.5.0','0.5.1','0.6.0','0.6.1','0.7.0','0.8.0','0.9.0',MODEL_VERSION].includes(String(obj.version)))throw Error('This file needs a compatible model version.');if(typeof obj.seed!=='number'||!Number.isInteger(obj.seed)||obj.seed<0||obj.seed>4294967295)throw Error('Invalid case number.');const oldSettings=obj.settings as Record<string,unknown>;const migrated=obj.version!==MODEL_VERSION?{...DEFAULTS,...oldSettings,connectedness:typeof oldSettings?.connectedness==='number'?oldSettings.connectedness:typeof oldSettings?.reach==='number'?(oldSettings.reach-1)*20:DEFAULTS.connectedness}:oldSettings;if(obj.version!==MODEL_VERSION&&typeof oldSettings?.evaluationCapacity==='number')migrated.evaluationCapacity=oldSettings.evaluationCapacity/5;const checked=validateSettings(migrated);const checkedContinuation=validateContinuation(obj.continuation);const checkedMonth=validateMonth(obj.monthOptions);if(obj.monthSeed!==undefined&&(typeof obj.monthSeed!=='number'||!Number.isInteger(obj.monthSeed)||obj.monthSeed<0||obj.monthSeed>4294967295))throw Error('Invalid month replay.');remember();monthOptions=checkedMonth;monthSeed=obj.monthSeed as number??42;continuation=checkedContinuation;seed=obj.seed;settings=checked;result=simulate(settings,seed);selected='';panel='outcomes';range=null;requestId++;persist();render();$('#change-text').textContent=obj.version===MODEL_VERSION?'Your world is restored. Change a dial or watch the story.':'Testing capacity now reaches 20/day. Your saved testing throughput has been preserved; outcomes have been recalculated.';}
function showSave(){openDialog('Keep this world.','SAVE / OPEN / SHARE',`<p>Save your settings and human-response replay. Reopening the same model version reproduces the result.</p><div class="export-line"><button class="primary" id="download-scenario">Download scenario</button><button class="secondary" id="copy-link">Copy scenario link</button></div><label class="import-label">Open a saved scenario<input id="import-scenario" type="file" accept="application/json,.json"></label><p>Links point to the current host. A localhost link only works on this computer; use a deployed site URL to share with others.</p>`);}

document.addEventListener('click',e=>{
  const target=e.target as Element;
  const stageButton=target.closest<HTMLElement>('[data-stage]');if(stageButton){enterStage(stageButton.dataset.stage as Stage);return;}
  const crumb=target.closest<HTMLElement>('[data-trail-index]');if(crumb){trail.splice(Number(crumb.dataset.trailIndex)+1);back();return;}
  const releaseButton=target.closest<HTMLElement>('[data-release]');if(releaseButton){const release=result.updates.releases.find(e=>e.id===Number(releaseButton.dataset.release));if(release){if(selected==='comms'){selected='';}inspect('comms');$('#readout').insertAdjacentHTML('afterbegin',`<div class="entry-callout"><strong>Day ${Math.floor(release.hour/24)+1} · Update ${release.id}</strong><p>${release.checked?'Tests missed this mistake.':'This update went live without testing.'} At hour ${release.hour}, it added ${settings.repair} hours of repair work in each of ${result.affectedRegions} affected regions.</p><p>The board shows the combined damage from the month. Repairs and backup stores carry over between failures.</p><button class="small-button" data-inspect="development">← All updates this month</button></div>`);$('#readout').scrollTop=0;guide(`Update ${release.id} → communications → ${result.powerOutage?'power and essential services':'connected services'}. The white border marks the part to explore.`);}return;}

  if(target.closest('#tour-button')){startTour();return;}
  if(target.closest('#open-month')){showMonth();return;}
  if(target.closest('#clear-selection')){clearSelection();return;}
  if(target.closest('#motion-toggle')){const on=document.documentElement.dataset.motion!=='on';document.documentElement.dataset.motion=on?'on':'off';$('#motion-toggle').textContent=on?'Motion on':'Motion off';$('#motion-toggle').setAttribute('aria-pressed',String(on));return;}
  if(target.closest('#panel-back')){back();return;}
  const rescue=target.closest<HTMLElement>('[data-rescue]');if(rescue){const option=protections(settings).find(p=>p.id===rescue.dataset.rescue);if(!option)return;const changes=settingChanges(settings,option.patch);if(!changes.length)return;const before=result;change({...settings,...option.patch});protectionReceipt=`<section class="protection-receipt" aria-live="polite"><span class="etched-label">SETTINGS CHANGED</span><h3>${option.title}</h3>${changes.map(c=>`<button data-setting-reveal="${c.key}">${c.name}<b>${settingValue(c.key,c.before)} → ${settingValue(c.key,c.after)}</b><small>${deckInfo.some(d=>d.key===c.key)?'Main dial':'World settings'} · inspect ↗</small></button>`).join('')}<p>${protectionEffect(before,result)}</p><button id="protection-undo">↶ Undo these changes</button></section>`;renderPanel();$('#readout').scrollTop=0;guide(protectionEffect(before,result));return;}
  if(target.closest('#scenario-receipt-close')){scenarioChangeReceipt='';renderPanel();return;}
  if(target.closest('#scenario-undo')){$('#undo-button').click();return;}
  if(target.closest('#protection-undo')){$('#undo-button').click();return;}
  const reveal=target.closest<HTMLElement>('[data-setting-reveal]');if(reveal){setPanel('advanced');const field=document.getElementById('adv-'+reveal.dataset.settingReveal);if(field){let parent=field.parentElement;while(parent){if(parent instanceof HTMLDetailsElement)parent.open=true;parent=parent.parentElement;}field.scrollIntoView({block:'center'});field.focus();}return;}
  const densityButton=target.closest<HTMLElement>('[data-density]');if(densityButton){density=densityButton.dataset.density as typeof density;focus(density==='compact'?'world':stage==='world'?'origins':stage==='rescue'?'recovery':'services');return;}

  const gateOpen=target.closest<HTMLElement>('[data-gate-open]');if(gateOpen){survivalGate=gateOpen.dataset.gateOpen as Gate;refreshContinuation();guide(survivalQuestions[continuation.route][survivalGate].scene+' Choose one of the two endings on this card.');return;}
  const survivalAnswer=target.closest<HTMLElement>('[data-survival-answer]');if(survivalAnswer){if(!evaluateContinuation(result,continuation).started)return;remember();survivalGate=survivalAnswer.dataset.gate as Gate;continuation[continuation.route][survivalGate]=survivalAnswer.dataset.survivalAnswer as Assumption;persist();refreshContinuation();const q=survivalQuestions[continuation.route][survivalGate];guide(survivalAnswer.dataset.survivalAnswer==='yes'?q.lost:survivalAnswer.dataset.survivalAnswer==='no'?q.saved:'This question is open again. Choose either ending on its card.');const choice=document.querySelector<HTMLButtonElement>(`[data-canvas-choice][data-gate="${survivalGate}"][data-survival-answer="${survivalAnswer.dataset.survivalAnswer}"]`);if(survivalAnswer.dataset.canvasChoice)choice?.focus({preventScroll:true});return;}
  const continuationRoute=target.closest<HTMLElement>('[data-continuation-route]');if(continuationRoute){const route=continuationRoute.dataset.continuationRoute as Route;remember();const needsWorld=!evaluateContinuation(result,{...continuation,route}).started;if(needsWorld){change({...DEFAULTS,...(route==='hostile'?pathwayPresets.control:{connectedness:100,fallback:0,tension:0})},false);continuation=freshContinuation();}continuation.route=route;survivalGate='power';persist();refreshContinuation();guide(needsWorld?`${route==='hostile'?'An agent people cannot stop':'A world after collapse'} is now set up. Choose an ending on the first card. Undo restores your previous world.`:'Follow this world’s survivors. Choose an ending on the first card.');return;}
  if(target.closest('#continuation-refuge')){remember();continuation[continuation.route].reach='no';survivalGate='reach';persist();refreshContinuation();return;}
  if(target.closest('#continuation-reset')){remember();const route=continuation.route;continuation[route]=freshContinuation()[route];survivalGate='power';persist();refreshContinuation();return;}

  const pathwayButton=target.closest<HTMLElement>('[data-pathway]');if(pathwayButton){const id=pathwayButton.dataset.pathway!;if(currentScenario(settings).id===id&&!currentScenario(settings).modified){enterStage('chain');return;}const before=settings;mode='case';trail.length=0;change({...DEFAULTS,...pathwayPresets[id]});scenarioChangeReceipt=scenarioReceipt(before,id,deckInfo.map(d=>d.key));guide('Scenario loaded. The readout lists what changed; click any setting to find its control.');selected='';inspect(({outage:'comms',research:'development',control:'control',health:'bio',information:'information',deliveries:'payments'} as Record<string,string>)[id]);return;}
  const interruptButton=target.closest<HTMLElement>('[data-interrupt]');if(interruptButton){const key=interruptButton.dataset.interrupt as keyof Settings;change({...settings,[key]:typeof settings[key]==='boolean'?true:100});return;}
  const regionButton=target.closest<HTMLElement>('[data-region]');if(regionButton){rememberPlace();selected=regionButton.dataset.inspect!;regionContext=Number(regionButton.dataset.region);panel='region';renderMap();renderPanel();$('#readout').scrollTop=0;revealPanel();return;}
  const regionDetail=target.closest<HTMLElement>('[data-region-detail]');if(regionDetail){rememberPlace();regionContext=Number(regionDetail.dataset.regionDetail);selected='';panel='region';renderPanel();renderMap();$('#readout').scrollTop=0;revealPanel();return;}
  const inspectButton=target.closest<HTMLElement>('[data-inspect]');if(inspectButton){inspect(inspectButton.dataset.inspect!);return;}
  const node=target.closest<SVGElement>('[data-node]');if(node){inspect(node.dataset.node!);return;}
  const panelButton=target.closest<HTMLElement>('[data-panel]');if(panelButton){setPanel(panelButton.dataset.panel as typeof panel);return;}
  const modeButton=target.closest<HTMLElement>('[data-mode]');if(modeButton){mode=modeButton.dataset.mode as typeof mode;render();return;}
  const focusButton=target.closest<HTMLElement>('[data-focus]');if(focusButton){focus(focusButton.dataset.focus!);return;}
  const stepButton=target.closest<HTMLElement>('[data-step]');if(stepButton){storyIndex=Number(stepButton.dataset.step);render();focusStory();return;}
  const id=target.closest<HTMLElement>('[id]')?.id;
  if(id==='story-prev'||id==='story-next'){storyIndex=Math.max(0,Math.min(storySteps().length-1,storyIndex+(id==='story-next'?1:-1)));render();focusStory();return;}
  if(id==='try-wide-failure'){trail.length=0;mode='case';change({...DEFAULTS,connectedness:100,crews:25,repairBackup:24,foodStores:48,regionDifference:50,responseBackup:72,collapseRegions:4,collapseDays:14});panel='collapse';render();return;}
  if(id==='keep-refuges'){mode='case';change({...settings,connectedness:Math.min(settings.connectedness,35),aidStrength:100,aidBudget:168});panel='collapse';render();return;}
  if(id==='protect-repairs'){mode='case';change({...settings,repairBackup:720,repairSupplies:168,supplyDelivery:100});panel='recovery';selected='';render();return;}
  if(id==='new-case'){scenarioChangeReceipt='';protectionReceipt='';clearFeedback();remember();seed=(seed+1)>>>0;range=null;requestId++;result=simulate(settings,seed);panel='outcomes';mode='case';persist();render();$('#change-text').textContent=`A different set of regional links and human decisions. Your settings stay the same.`;}
  if(id==='trace-selected'||id==='trace-button'){trace();}
  if(id==='download-scenario'){const blob=new Blob([JSON.stringify(scenarioObject(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`switchboard-case-${seed}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  if(id==='copy-link'){const url=new URL(location.href);url.hash='scenario='+btoa(JSON.stringify(scenarioObject()));navigator.clipboard.writeText(url.href).then(()=>toast('Scenario link copied.')).catch(()=>toast('Clipboard unavailable. Download the scenario instead.'));}
});
document.addEventListener('keydown',e=>{const el=e.target as Element;if(el.matches('[data-gate-open]')&&['Enter',' '].includes(e.key)){e.preventDefault();(el as HTMLElement).dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(el.matches('[data-node]')&&['Enter',' '].includes(e.key)){e.preventDefault();inspect((el as SVGElement).dataset.node!);}if(e.key==='Escape'&&!document.querySelector('#quick-tour')&&!$<HTMLDialogElement>('#dialog').open){back();}});
$('#readout').addEventListener('input',e=>{const input=e.target as HTMLInputElement;if(!input.dataset.setting)return;scenarioChangeReceipt='';protectionReceipt='';const key=input.dataset.setting as keyof Settings;const before=result;remember();settings={...settings,[key]:input.type==='checkbox'?input.checked:key==='researchSpeed'?Number(input.value)/6:Number(input.value)};result=simulate(settings,seed);range=null;requestId++;persist();if(input.type==='range')input.previousElementSibling!.querySelector('output')!.textContent=key==='researchSpeed'?`${input.value} updates/month`:key==='evaluationCapacity'?`${Number(input.value)/5} tests/day`:`${input.value} ${input.dataset.unit}`;feedback(before);render(true);document.querySelectorAll('.release-policy-status').forEach(el=>el.textContent=releaseExplanation(settings,result.updates));});
document.addEventListener('change',async e=>{const input=e.target as HTMLInputElement;if(input.id!=='import-scenario')return;try{const f=input.files?.[0];if(!f)return;if(f.size>100000)throw Error('Scenario file is too large.');loadScenario(JSON.parse(await f.text()));$<HTMLDialogElement>('#dialog').close();toast('Scenario restored.');}catch(err){toast(err instanceof Error?err.message:'Unable to open this scenario.');}});
$('#about-button').addEventListener('click',showAbout);$('#save-button').addEventListener('click',showSave);$('#extinction-button').addEventListener('click',showExtinction);
$('#dialog-close').addEventListener('click',()=>$<HTMLDialogElement>('#dialog').close());
$('#advanced-button').addEventListener('click',()=>setPanel(panel==='advanced'?'outcomes':'advanced'));
$('#undo-button').addEventListener('click',()=>{const old=history.pop();if(!old)return;scenarioChangeReceipt='';protectionReceipt='';clearFeedback();settings=old.settings;seed=old.seed;continuation=old.continuation;monthOptions=old.monthOptions;monthSeed=old.monthSeed;result=simulate(settings,seed);range=null;requestId++;persist();render();$('#change-text').textContent="Your last change is undone. You are back where you were.";});
$('#reset-button').addEventListener('click',()=>{scenarioChangeReceipt='';protectionReceipt='';clearFeedback();remember();settings={...DEFAULTS};continuation=freshContinuation();monthOptions={...MONTH_DEFAULTS};monthSeed=42;seed=42;result=simulate(settings,seed);selected='';panel='pathways';range=null;requestId++;persist();enterStage('world');$('#change-text').textContent='Opening scenario restored. Watch the story, then try to keep the hospital working.';animateSetup();});

function updateCamera(){if(panel==='beyond'){$('#world-svg').setAttribute('viewBox','0 0 1080 800');return;}
  const viewport=$('#viewport'),ratio=viewport.clientWidth/Math.max(1,viewport.clientHeight);camera.h=camera.w/ratio;
  clampCamera();$('#world-svg').setAttribute('viewBox',`${camera.x} ${camera.y} ${camera.w} ${camera.h}`);
  $('#zoom-label').textContent=`${Math.round(viewport.clientWidth/camera.w*100)}%`;
  $('#mini-map').hidden=density==='compact';
  const r=$('#mini-window');if(r)for(const [k,v] of Object.entries({x:camera.x,y:camera.y,width:camera.w,height:camera.h}))r.setAttribute(k,String(v));
  document.querySelectorAll<HTMLElement>('[data-density]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.density===density)));
}
function clampCamera(){if(density==='compact'){camera.x=-(camera.w-WORLD.width)/2;camera.y=-(camera.h-950)/2;return;}camera.x=Math.max(-35,Math.min(WORLD.width-camera.w+35,camera.x));camera.y=Math.max(-35,Math.min(Math.max(0,WORLD.height-camera.h)+35,camera.y));}
function zoom(factor:number,px=.5,py=.5){if(density==='compact'){focus('services');return;}density='normal';const nw=Math.max(450,Math.min(2800,camera.w/factor)),nh=nw*camera.h/camera.w;camera.x+=(camera.w-nw)*px;camera.y+=(camera.h-nh)*py;camera.w=nw;camera.h=nh;updateCamera();}
function focus(area:string){
  const centers:Record<string,[number,number]>={origins:[400,445],services:[980,470],health:[1370,515],recovery:[1880,515],military:[1070,200]};
  if(area==='world'){density='compact';const ratio=$('#viewport').clientWidth/Math.max(1,$('#viewport').clientHeight);camera.w=Math.max(WORLD.width,WORLD.height*ratio);camera.x=0;camera.y=0;}
  else {density='normal';camera.w=Math.max(720,$('#viewport').clientWidth/.84);const center=centers[area]||centers.services;camera.x=center[0]-camera.w/2;camera.y=center[1]-(camera.w/(Math.max(1,$('#viewport').clientWidth)/Math.max(1,$('#viewport').clientHeight)))/2;}
  renderMap();viewArea=area;$('#view-label').textContent=area==='world'?'Whole circuit': 'Drag or scroll to travel · Ctrl + scroll to zoom';updateCamera();
}
function focusNode(id:string){const n=nodeById[id==='nuclear'?'military':id];if(!n||density==='compact')return;camera.x=n.x+105-camera.w/2;camera.y=n.y+56-camera.h/2;updateCamera();}
function focusStory(){const ids=storySteps()[storyIndex]?.nodes||[];focusNode(ids[Math.floor(ids.length/2)]||'comms');}
$('#zoom-in').addEventListener('click',()=>zoom(1.25));$('#zoom-out').addEventListener('click',()=>zoom(.8));$('#home-view').addEventListener('click',()=>focus('world'));
const viewport=$('#viewport');let pan:{x:number;y:number;cx:number;cy:number}|null=null;
viewport.addEventListener('pointerdown',e=>{if(panel==='beyond'||(e.target as Element).closest('[data-node]'))return;pan={x:e.clientX,y:e.clientY,cx:camera.x,cy:camera.y};viewport.setPointerCapture(e.pointerId);viewport.classList.add('dragging');});
viewport.addEventListener('pointermove',e=>{if(!pan)return;const scale=viewport.clientWidth/camera.w;camera.x=pan.cx-(e.clientX-pan.x)/scale;camera.y=pan.cy-(e.clientY-pan.y)/scale;updateCamera();});
viewport.addEventListener('pointerup',e=>{if(pan&&Math.hypot(e.clientX-pan.x,e.clientY-pan.y)<5&&selected)back();pan=null;viewport.classList.remove('dragging');});viewport.addEventListener('pointercancel',()=>{pan=null;viewport.classList.remove('dragging');});
viewport.addEventListener('wheel',e=>{if(panel==='beyond')return;e.preventDefault();if(e.ctrlKey||e.metaKey){const rect=viewport.getBoundingClientRect();zoom(e.deltaY<0?1.1:1/1.1,(e.clientX-rect.left)/rect.width,(e.clientY-rect.top)/rect.height);}else{camera.x+=(e.shiftKey?e.deltaY:e.deltaX)*camera.w/viewport.clientWidth;camera.y+=(e.shiftKey?0:e.deltaY)*camera.w/viewport.clientWidth;updateCamera();}},{passive:false});
viewport.addEventListener('keydown',e=>{if(panel==='beyond'||(e.target as Element).closest('[data-node]'))return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','Home'].includes(e.key)){e.preventDefault();if(e.key==='Home'){focus('world');return;}if(e.key==='+'||e.key==='=')zoom(1.2);else if(e.key==='-')zoom(1/1.2);else{camera.x+=(e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0)*camera.w*.1;camera.y+=(e.key==='ArrowDown'?1:e.key==='ArrowUp'?-1:0)*camera.h*.1;updateCamera();}}});
$('#mini-map').addEventListener('click',e=>{const rect=$('#mini-map').getBoundingClientRect();camera.x=(e.clientX-rect.left)/rect.width*WORLD.width-camera.w/2;camera.y=(e.clientY-rect.top)/rect.height*WORLD.height-camera.h/2;updateCamera();});
$('#mini-map').addEventListener('keydown',e=>{if(e.key==='Enter'){focus('world');}});
function toggleDesk(){const closed=$('#main').classList.toggle('desk-closed');$('#desk-toggle').setAttribute('aria-expanded',String(!closed));requestAnimationFrame(()=>updateCamera());}
$('#desk-toggle').addEventListener('click',toggleDesk);$('#desk-close').addEventListener('click',toggleDesk);
new ResizeObserver(()=>updateCamera()).observe(viewport);
function rescuePanel(){return panelHeader('Protect the world')+`<h2 class="inspector-title">Protect the world</h2><p class="inspector-copy">Choose a change to your world settings. See exactly what it changes, then whether it helps.</p>${protectionReceipt}`+protections(settings).map(p=>{const changes=settingChanges(settings,p.patch);return `<button class="protection-choice" data-rescue="${p.id}" ${changes.length?'':'disabled'}><strong>${p.title}</strong><small>${changes.length?changes.map(c=>`${c.name}: ${settingValue(c.key,c.before)} → ${settingValue(c.key,c.after)}`).join('<br>'):'Already set · nothing to change'}</small><span>${changes.length?'Apply these settings →':'✓ Already set'}</span></button>`;}).join('')+`<button class="small-button" data-panel="advanced">⚙ World settings</button>`;}
function collapsePanel(){
  const c=result.civilisation,days=(hours:number)=>(hours/24).toFixed(1);
  const title=result.nuclear?'Wider outcome unknown':c.crossedAt!==null?(c.recoveredAt!==null?'Back from the brink.':'The world is coming apart.'):c.endStatus==='disrupted'?'Lifelines are still failing.':'The world holds together.';
  const plot=c.frames.filter((_,i)=>i%6===0).map(f=>`${10+180*f.time/720},${90-70*f.failingRegions/6}`).join(' ');
  return panelHeader('CIVILISATION')+`<h2 class="inspector-title">${title}</h2><p class="inspector-copy">${result.nuclear?'The service model does not calculate nuclear damage. These service results cannot establish the wider outcome.':`At the worst point, ${c.peakRegions} of 6 regions lose their essential lifelines together. The longest stretch across ${settings.collapseRegions} or more regions lasts ${days(c.longestHours)} days.`}</p>
    <div class="collapse-chain"><div><span>ESSENTIALS</span><b>Power + healthcare + food</b><small>Each below half capacity</small></div><div><span>RESPONSE</span><b>Local coordination also fails</b><small>Below half capacity</small></div><div><span>EXTENT × TIME</span><b>${settings.collapseRegions} of 6 regions · ${settings.collapseDays} days</b><small>Without a break</small></div></div>
    <svg class="repair-chart" viewBox="0 0 200 120" role="img" aria-label="Regions failing the combined test over 30 days. Peak ${c.peakRegions} regions."><path d="M10 20H190M10 90H190" stroke="#aabbcc33"/><path d="M10 ${90-70*settings.collapseRegions/6}H190" stroke="#ffd17788" stroke-dasharray="3 3"/><polyline points="${plot}" fill="none" stroke="#ff9870" stroke-width="2"/><text x="1" y="20">6</text><text x="1" y="92">0</text><text x="169" y="${87-70*settings.collapseRegions/6}">${settings.collapseRegions}+</text><text x="10" y="108">DAY 0</text><text x="159" y="108">DAY 30</text></svg>
    <div class="comparison"><div><span>Collapse begins</span><b>${c.crossedAt===null?'Avoided':`Day ${days(c.crossedAt)}`}</b></div><div><span>Back on its feet</span><b>${c.recoveredAt===null?'—':`Day ${days(c.recoveredAt)}`}</b></div><div><span>At day 30</span><b>${({functioning:'Services working',recovered:'Recovered',disrupted:'Still disrupted',collapse:'Still in crisis'} as Record<string,string>)[c.endStatus]}</b></div><div><span>Outside the network fault</span><b>${c.independentRegions} / 6</b></div><div><span>Help delivered</span><b>${c.aidReceived.toFixed(0)} packages</b></div></div>
    <div class="entry-callout">${result.affectedRegions<settings.collapseRegions?`This network fault reaches ${result.affectedRegions} regions. Collapse here needs ${settings.collapseRegions} regions to lose essentials together. What if the failure spread further?`:'Shared failure is only the start. Reserves, working neighbours and repairs decide whether it lasts.'}</div><button class="small-button" id="try-wide-failure">New scenario: six regions lose their lifelines ↗</button><p class="preset-note">Replaces starting settings: six connected regions, fewer crews, short food and tool backups. Undo restores your world.</p><button class="small-button" id="keep-refuges">Keep two regions independent ↗</button><button class="small-button" data-panel="advanced">Inspect assumptions ↗</button><button class="small-button" data-inspect="extinction">What would extinction also require? ↗</button>
    <details class="model-details"><summary>Why this definition?</summary><p class="rule-copy">This is a visible, adjustable scenario boundary. There is no universally established numerical definition of civilisation collapse. Six equal-weight regions stand in for a connected world; they are not countries or population estimates. Short outages and one devastated region do not automatically meet this definition.</p><p class="rule-copy">Recovery requires every region to regain the essential basket and coordination for 24 hours. An earlier crossing is kept in the record. Thirty days is the calculation limit, not proof of permanent failure. Nuclear consequences and extinction are not calculated.</p>${evidenceNote('collapse')}</details>`;
}
function spreadPanel(){return `<div class="spread-routes">${result.spread.reasons.map((reason,i)=>`<button class="spread-route ${result.regions[i].comms?'hit':'held'}" data-region-detail="${i}"><b>Region ${i+1} ↗</b><span>${result.incident?reason:'No network fault starts.'}</span></button>`).join('')}</div><button class="small-button" id="new-case">Try another version of events ↻</button><button class="small-button" data-panel="range">See the range of possible spread ↗</button>`;}
function regionPanel(index:number){
  const c=result.civilisation,r=c.regions[index],m=r.recovery;
  return panelHeader(r.name.toUpperCase())+`<h2 class="inspector-title">${!r.exposed?(m.healthcareGap?'Network working; care under pressure.':'Its separate network keeps working.'):m.completed?`Repaired after ${m.restoredAt} hours.`:'Still disrupted at day 30.'}</h2><p class="inspector-copy">${result.incident?result.spread.reasons[index]:'No network fault starts in this scenario.'} This region holds ${Math.round(r.reserveFactor*100)}% of the reference backup stores. ${r.aidSent>0?'It sends help after protecting its own essential needs.':r.aidReceived>0?'Other regions send help to its repair teams.':''}</p><div class="comparison">${[['Hospital backup',r.settings.reserves.toFixed(0)+'h'],['Tool backup',r.settings.repairBackup.toFixed(0)+'h'],['Stored food',r.settings.foodStores.toFixed(0)+'h'],['Hospital power gap',m.hospitalGap+'h'],['Care below demand',m.healthcareGap+'h'],['Food supply shortfall',m.foodShortageHours+'h'],['All essentials + response failing',r.deprivationHours+'h'],['Help sent',r.aidSent.toFixed(1)+' packages'],['Help received',r.aidReceived.toFixed(1)+' packages'],['Unused arrivals',r.aidUnused.toFixed(1)+' packages']].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}</div><button class="small-button" data-panel="collapse">See the whole-world outcome ↗</button>`;
}
function recoveryPanel(){
  const rm=result.recoveryModel;
  const end=rm.observedHours||1;
  const points=rm.frames.filter((_,i)=>i%6===0||i===rm.frames.length-1).map(f=>`${10+180*f.time/end},${100-80*f.work/settings.repair}`).join(' ');

  return panelHeader('REGION 1 · REPAIR')+`<h2 class="inspector-title">${rm.status==='unneeded'?'The fault was stopped.':rm.completed?`Repaired after ${rm.restoredAt} hours.`:rm.status==='stalled'?'Repairs have stalled.':'Still repairing at day 30.'}</h2><p class="inspector-copy">${result.nuclear?'Network failures only. Nuclear damage is not calculated.':rm.status==='unneeded'?'There is no repair job to do.':rm.completed?'The network works again. The damage while it was down still matters.':'Later recovery is unknown. The calculation stops at 30 days.'}</p>
    <div class="repair-progress"><strong>${Math.floor(rm.progress*100)}%</strong><span>of repair work finished</span><div><i style="width:${rm.progress*100}%"></i></div></div>
    ${result.incident?`<svg class="repair-chart" viewBox="0 0 200 125" role="img" aria-label="Repair progress over ${end} hours; ${Math.floor(rm.progress*100)} percent complete"><path d="M10 20H190M10 60H190M10 100H190" stroke="#aabbcc25"/><polyline points="${points}" fill="none" stroke="#76edcf" stroke-width="2.5"/><text x="10" y="119">START</text><text x="140" y="119">${end} HOURS</text></svg><p class="rule-copy">Required across all failures: ${rm.final.target} full-speed work hours.<br>${rm.completed?`Elapsed: ${rm.restoredAt} hours.`:`Done: ${rm.final.work.toFixed(1)} work hours.`}</p>`:''}
    ${rm.milestones.map(m=>`<div class="recovery-event"><b>${m.time}h</b><span>${esc(m.description)}</span></div>`).join('')}
    ${result.incident&&!rm.completed?`<p class="inspector-copy">Main limit at day 30: <strong>${esc(rm.final.limiting)}</strong>.</p>`:''}
    <button class="small-button" data-panel="advanced">Change repair resources ↗</button>${result.incident?'<button class="small-button" id="protect-repairs">Try protected repair supplies ↗</button>':''}
    <details class="model-details"><summary>Rules, stocks & evidence</summary><p class="rule-copy">One hour at a time, crews do as much work as people, coordination, tool power and materials allow. Hospitals and food support affect how many workers can stay on the job. A longer outage can therefore make repairs slower.</p><p class="rule-copy">Repair stock: ${settings.repairSupplies} initially + ${rm.suppliesDelivered.toFixed(1)} delivered − ${rm.suppliesUsed.toFixed(1)} used = ${rm.final.parts.toFixed(1)} left. Backups for hospitals, fridges and tools are separate stocks. They are not refilled in this case.</p><p class="rule-copy">Hourly steps; 30-day limit. Numerical effects are educational assumptions. This panel describes Region 1. The civilisation panel checks all six regions. Deaths are not calculated.</p>${evidenceNote('recovery')}</details>`;
}
function storySteps(){
  const r=result;
  const steps=[{nodes:['ai','access'],time:'THE MONTH',title:r.pathways.harmfulOperation&&r.incident?'An agent disrupts the network.':r.incident?`${r.updates.releases.filter(e=>e.fault).length} faulty updates escape.`:'No update causes a network failure.',copy:r.pathways.harmfulOperation&&r.incident?'The agent has access to connected services and a harmful goal. It keeps undoing repairs until people stop it.':r.incident?'It has permission to change the live network. People lose calls and messages when the update goes wrong.':`${result.updates.made} updates produced; none caused a network failure. Change project pace, mistakes or checks to explore why.`}];
  if(!r.incident&&(r.pathways.healthIntroduced||r.pathways.misinformation))steps.length=0;
  else if(!r.incident&&settings.healthChallenge)steps[0]={nodes:['bio'],time:'THE START',title:'A barrier stops the health threat.',copy:settings.screening?'Screening stops this threat before it reaches people. Hospitals do not face the extra surge.':!settings.physicalAccess?'The person trying to cause harm cannot carry it out in the physical world.':!settings.maliciousActor?'Nobody is trying to use the scientific help to cause harm.':'This AI cannot provide the scientific help required by this route.'};
  else if(!r.incident&&settings.informationCampaign)steps[0]={nodes:['information'],time:'THE START',title:'Trusted instructions get through.',copy:'The false-message campaign does not undermine the emergency response with these settings.'};
  for(const event of r.pathways.events.filter(e=>e.id!=='development'))steps.push({nodes:[event.id.startsWith('bio')?'bio':event.id,...event.parents],time:event.time<0?'30 DAYS BEFORE':`AFTER ${event.time} HOURS`,title:({'bio-peak':'The hospital faces peak demand.','bio-response':'The extra demand eases.',development:'Research meets a checking bottleneck.',control:r.pathways.controlLost?'The stop order fails.':'People stop the agent.',bio:'More people need care at once.',information:'False messages weaken the response.'} as Record<string,string>)[event.id],copy:event.description});
  if(settings.sharedPayments||settings.sharedTransport)steps.push({nodes:['comms','payments','transport','supplies','food'],time:`AFTER ${r.updates.releases.find(e=>e.fault)?.hour??0} HOURS`,title:'Supplies need more than a warehouse.',copy:`Payments fall as low as ${Math.round(Math.min(...r.recoveryModel.frames.map(f=>f.payments))*100)}%; transport as low as ${Math.round(Math.min(...r.recoveryModel.frames.map(f=>f.transport))*100)}%. Deliveries can only move as fast as their weakest required service.`});
  for(const e of r.updates.releases.filter(e=>e.fault).slice(0,3))steps.push({nodes:['development','access','comms'],time:`AFTER ${e.hour} HOURS`,title:`Update ${e.id} goes wrong.`,copy:`${e.checked?'Tests miss this mistake.':'It goes live without testing.'} Calls fail across ${r.affectedRegions} regions, adding ${settings.repair} hours of repair work. ${r.updates.releases.filter(e=>e.fault).length>3?'Open the month readout above the map to see every faulty update.':''}`});
  if(r.incident){
  steps.push({nodes:['access','comms','spread'],time:`AFTER ${r.updates.releases.find(e=>e.fault)?.hour??0} HOURS`,title:`Each escaped fault reaches ${r.affectedRegions} regions.`,copy:`${r.spread.routes.filter(x=>x==='shared').length} other regions receive the same faulty update. ${r.spread.routes.filter(x=>x==='dependency').length} more depend on services that fail elsewhere. ${6-r.affectedRegions} keep this network failure out. Select a region in the strip below to see its route.`});
  steps.push({nodes:['comms','power','emergency','fallback'],time:`AFTER ${r.updates.releases.find(e=>e.fault)?.hour??0} HOURS`,title:r.powerOutage?'The outage reaches power controls.':'Power keeps running.',copy:`${r.powerOutage?'The power system uses the failed network. Electricity is cut too.':'Its power controls are separate from this failure.'} ${r.emergencyGap?`Emergency teams have trouble taking calls and sending help. Separate radios cover ${settings.fallback}% of their normal response.`:'Separate radios keep emergency teams working.'}`});
  if(r.warning)steps.push({nodes:['comms','checks','warning','military'],time:`AFTER ${(r.pathways.harmfulOperation?0:r.updates.releases.find(e=>e.fault)?.hour??0)+settings.decisionTime/60} HOURS`,title:r.verified?'Someone catches the false warning.':r.escalation?'Leaders act on a false warning.':'The warning does not start a conflict.',copy:r.verified?'AI wrongly warns of an attack. People check another source in time and reject it. The power outage still needs fixing.':r.escalation?'AI wrongly warns of an attack. Checks fail to stop it, and rivals already on edge respond by escalating the crisis.':`AI wrongly warns of an attack. ${settings.tension<50?'Rivals are calm enough not to escalate.':'In this case, people choose not to escalate.'}`});
  if(r.nuclear)steps.push({nodes:['military'],time:`AFTER ${(r.nuclearAt??0)+settings.decisionTime/60+1} HOURS`,title:'A further human choice: nuclear use.',copy:'Leaders go on to use nuclear weapons. The service panel cannot calculate the destruction or recovery that follows.'});
  }
  const rm=r.recoveryModel;
  const milestoneNodes:Record<string,string[]>={hospital:['hospital','crews','repair'],cold:['power','food'],tools:['power','repair'],food:['food','crews','repair'],supplies:['supplies','repair'],stalled:['repair','recovery'],restored:['repair','recovery']};
  for(const m of rm.milestones)steps.push({nodes:milestoneNodes[m.kind]||['repair'],time:`AFTER ${m.time} HOURS`,title:({hospital:'Hospital trouble slows the repair crew.',cold:'Food warehouses lose refrigeration.',tools:'The repair tools lose power.',food:'Workers run short of food.',supplies:'Crews run short of supplies.',stalled:'Repair work stops.',restored:'Region 1’s network is repaired.'} as Record<string,string>)[m.kind],copy:m.description+(m.kind==='restored'&&r.nuclear?' This does not calculate recovery from nuclear weapons.':'')});
  if(!rm.completed)steps.push({nodes:['repair','recovery'],time:'AT DAY 30',title:rm.status==='stalled'?'The repair is stalled.':'The repair is not finished.',copy:`${Math.floor(rm.progress*100)}% of the work is done. ${rm.status==='stalled'?'Work has stopped with these resources.':'Crews are still making progress.'} What happens after day 30 is outside this calculation.`});
  if(r.civilisation.firstAidUsedAt!==null)steps.push({nodes:['aid','repair'],time:`AFTER ${r.civilisation.firstAidUsedAt} HOURS`,title:'Help reaches the damaged regions.',copy:'Working regions send spare crews, powered tools, food and materials. Their own essential supplies are kept at home.'});
  if(r.civilisation.crossedAt!==null&&!r.nuclear)steps.push({nodes:['governance','hospital','food','power'],time:`AFTER ${r.civilisation.crossedAt} HOURS`,title:'The world is coming apart.',copy:`At least ${settings.collapseRegions} regions have lost most power, healthcare, food support and local coordination together for ${settings.collapseDays} days. People are losing the essentials they need, together, for too long.`});
  if(r.civilisation.recoveredAt!==null&&!r.nuclear)steps.push({nodes:['aid','repair','recovery'],time:`AFTER ${r.civilisation.recoveredAt} HOURS`,title:'Services recover after the crisis.',copy:'All six regions regain essential support and coordination for a full day. They have come through a collapse and started to rebuild.'});
  const hour=(text:string)=>text==='30 DAYS BEFORE'?-720:text==='THE MONTH'||text==='THE START'?-2:text==='AT ONCE'?-1:text==='AFTER ESCALATION'?settings.decisionTime/60+1:text==='AT DAY 30'?720:text.startsWith('WITHIN')?settings.decisionTime/60:Number(text.match(/[\d.]+/)?.[0]||0);
  return steps.sort((a,b)=>hour(a.time)-hour(b.time));
}
function trace(){enterStage('chain');}
function renderImpact(){
  const count=result.affectedRegions;
  $('#impact').innerHTML=`<div class="impact-heading"><span class="etched-label">DAMAGE DURING THIS MONTH</span><span class="region-key"><i class="dot mint"></i> Holding <i class="dot coral"></i> Hit <i class="dot" style="background:#ffce69"></i> Strained</span><button data-inspect="spread">${count===0?'NETWORK HELD':count===1?'ONE REGION':count<6?'SEVERAL REGIONS':'ALL SIX REGIONS'} <span>${count} / 6</span> ↗</button></div><div class="region-grid">${result.regions.map(r=>`<div class="region ${r.comms?'affected':''}"><button class="region-title" data-region-detail="${result.regions.indexOf(r)}">${r.name} ↗</button><div>${(['comms','power','hospital','food','emergency'] as const).map((key,i)=>`<button class="region-cell ${r[key]?(mode==='conditions'||key==='emergency'&&Math.min(...result.civilisation.regions[result.regions.indexOf(r)].recovery.frames.map(f=>f.emergency))>0||key==='hospital'&&Math.min(...result.civilisation.regions[result.regions.indexOf(r)].recovery.frames.map(f=>f.healthcare))>=.5?'exposed':'harm'):'safe'}" data-inspect="${key}" data-region="${result.regions.indexOf(r)}" aria-label="${r.name}: ${['calls','power','hospital','food supply','emergency response'][i]} ${r[key]?(mode==='conditions'?'at risk':'interrupted during this month'):'available'}" data-tip="${['Calls','Power','Hospital','Food','Emergency help'][i]}: ${r[key]?(mode==='conditions'?'at risk':'interrupted during this month'):'available'}"><svg viewBox="0 0 24 24" aria-hidden="true">${icon(['signal','bolt','cross','building','radar'][i])}</svg></button>`).join('')}</div></div>`).join('')}</div>`;
}


