function animateSetup(){cancelAnimationFrame(setupFrame);const started=performance.now();function frame(now:number){const t=Math.min(1,(now-started)/1800),progress=1-Math.pow(1-t,3);for(const d of deckInfo){const c=controls[d.key],fraction=dialFraction(d.key,settings[d.key]);const bank=$(`[data-bank="${d.key}"]`);bank.querySelector<HTMLElement>('.dial-wrap')!.style.setProperty('--fill',`${270*fraction*progress}deg`);bank.querySelector<HTMLElement>('.dial')!.style.setProperty('--angle',`${-135+270*fraction*progress}deg`);}if(t<1)setupFrame=requestAnimationFrame(frame);else updateDeck();}frame(started);}
