const tourSteps=[
 {target:'.current-scenario',title:'This is your current scenario',copy:'Select this card to watch what happens. The other cards load different starting settings. You can always come back to Set the world.'},
 {target:'[data-bank="reserves"]',title:'Turn a dial',copy:'Drag up or down, or use the arrow keys. Hospital backup means how long essential equipment can run without mains power. Changes take effect straight away.'},
 {target:'#readout',title:'Watch the story',copy:'Use Next to follow one event at a time. The map moves to the relevant connections. You do not have to wait for simulated days to pass.'},
 {target:'#readout',title:'Choose a protection',copy:'Each choice lists the settings it will change. After applying it, a receipt shows what changed and whether it helped. Already set means there is nothing new to apply.'},
 {target:'#world-settings-button',title:'All the settings live here',copy:'Some protections change settings beyond the eight dials. Open World settings to find them. A setting in a protection receipt takes you straight to that control.'}
];
function endTour(){document.querySelector('#quick-tour')?.remove();document.querySelectorAll('.tour-target').forEach(e=>e.classList.remove('tour-target'));try{localStorage.setItem('switchboard-tour-seen','yes');}catch{}tourIndex=-1;$('#tour-button').focus({preventScroll:true});}
function startTour(){tourIndex=0;showTour();}
function showTour(){document.querySelector('#quick-tour')?.remove();document.querySelectorAll('.tour-target').forEach(e=>e.classList.remove('tour-target'));
 const step=tourSteps[tourIndex];if(!step){endTour();return;}
 if(tourIndex===0)enterStage('world');if(tourIndex===1){$('#main').classList.remove('desk-closed');$('#desk-toggle').setAttribute('aria-expanded','true');}if(tourIndex===2)enterStage('chain');if(tourIndex===3)enterStage('rescue');
 const target=document.querySelector(step.target);target?.classList.add('tour-target');target?.scrollIntoView({block:'nearest'});
 const card=document.createElement('aside');card.id='quick-tour';card.className='tour-card';card.setAttribute('aria-label','Quick tour');card.innerHTML=`<span class="etched-label">QUICK TOUR · ${tourIndex+1} / ${tourSteps.length}</span><h2>${step.title}</h2><p>${step.copy}</p><nav><button data-tour="close">End tour</button>${tourIndex?'<button data-tour="back">← Back</button>':''}<button class="tour-next" data-tour="next">${tourIndex===tourSteps.length-1?'Finish tour':'Next →'}</button></nav>`;document.body.append(card);card.querySelector<HTMLButtonElement>('.tour-next')?.focus({preventScroll:true});}
document.addEventListener('click',e=>{const action=(e.target as Element).closest<HTMLElement>('[data-tour]')?.dataset.tour;if(!action)return;if(action==='close')endTour();else if(action==='start')startTour();else{tourIndex+=action==='back'?-1:1;showTour();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('#quick-tour')){endTour();}});
try{if(!localStorage.getItem('switchboard-tour-seen'))setTimeout(()=>{if(document.querySelector('#quick-tour')||$<HTMLDialogElement>('#dialog').open)return;const invite=document.createElement('aside');invite.id='quick-tour';invite.className='tour-card';invite.innerHTML='<span class="etched-label">NEW HERE?</span><h2>Meet the machine</h2><p>A short tour shows you where to start, what you can change, and how to see what happened.</p><nav><button data-tour="close">Explore on my own</button><button class="tour-next" data-tour="start">Start quick tour →</button></nav>';document.body.append(invite);},2100);}catch{}
